const bookList = document.getElementById("book-list");
const searchInput = document.getElementById("search-input");
const genreFilter = document.getElementById("genre-filter");
const themeButton = document.getElementById("theme-toggle");

function applyMainTheme() {
  const isDark = localStorage.getItem("darkMode") === "true";
  if(isDark) document.body.classList.add("dark-mode");
  themeButton.textContent = isDark ? "Light Mode" : "Dark Mode";
}

themeButton.addEventListener("click", () => {
  document.body.classList.toggle("dark-mode");
  const nowDark = document.body.classList.contains("dark-mode");
  localStorage.setItem("darkMode", nowDark);
  themeButton.textContent = nowDark ? "Light Mode" : "Dark Mode";
});

function displayBooks() {
    const searchText = searchInput.value.toLowerCase();
    const selectedGenre = genreFilter.value;

    const filteredBooks = books.filter(book => {
        const matchesSearch = book.title.toLowerCase().includes(searchText);
        const matchesGenre = selectedGenre === "All Genres" || book.genre === selectedGenre;
        return matchesSearch && matchesGenre;
    });

    bookList.innerHTML = "";
    document.getElementById("results-count").textContent = `${filteredBooks.length} stories found`;

    filteredBooks.forEach(book => {
        const card = document.createElement("article");
        card.className = "book-card";

        card.innerHTML = `
            <img src="${book.cover}" alt="Cover of ${book.title}">
            <div class="book-info">
                <p class="genre">${book.genre}</p>
                <h3>${book.title}</h3>
                <p>By ${book.author}</p>
                <p>${book.synopsis}</p>
                <button class="read-button">Read Story</button>
                <button class="like-button">♡ Like</button>
            </div>
        `;

        card.querySelector(".read-button").addEventListener("click", () => {
            const shouldBeDark = localStorage.getItem("darkMode") === "true";

            const storyWindow = window.open("", "_blank");
            storyWindow.document.write(`
                <!DOCTYPE html>
                <html lang="en">
                <head>
                    <meta charset="UTF-8">
                    <meta name="viewport" content="width=device-width, initial-scale=1">
                    <title>${book.title}</title>
                    <style>
                         body {
                           max-width: 720px;
                           margin: 2rem auto;
                           padding: 0 1.25rem;
                           font-family: Georgia, serif;
                           line-height: 1.85;
                           color: #29213d;
                           background: #D3B9A7;
                           min-height: 100vh;
                         }
                         body.dark-mode {
                           background: #22272E;
                           color: #E6EDF3;
                         }
                         .story‑content {
                           font‑size: clamp(1rem, 2.2vw, 1.15rem);
                         }
                         img {
                           width: 180px;
                           max‑width: 100%;
                           border‑radius: 10px;
                         }
                         a { color: #19110C; }
                         body.dark‑mode a { color: #93B4F3; }

                     </style>
                </head>
                <body ${shouldBeDark ? 'class="dark-mode"' : ''}>
            <a href="index.html" target="_self" onclick="window.close();">← Close Story</a>
                    <h1>${book.title}</h1>
                    <p>By ${book.author}</p>
                    <p><strong>Genre:</strong> ${book.genre}</p>
                    <p><strong>Synopsis:</strong> ${book.synopsis}</p>
                    <img src="${book.cover}" alt="Book cover">
                    <h2>${book.chapter}</h2>
                    <p>${book.story}</p>
                    <p><em>— End of Chapter 1 —</em></p>
                </body>
                </html>
            `);
            storyWindow.document.close();
        });

        const likeButton = card.querySelector(".like-button");
        likeButton.addEventListener("click", () => {
            const liked = likeButton.classList.toggle("liked");
            likeButton.textContent = liked ? "♥ Liked" : "♡ Like";
        });

        bookList.appendChild(card);
    });
}


const genres = [...new Set(books.map(book => book.genre))];
genreFilter.innerHTML = `<option value="All Genres">All Genres</option>`;
genres.forEach(genre => {
    const opt = document.createElement("option");
    opt.value = genre;
    opt.textContent = genre;
    genreFilter.appendChild(opt);
});

searchInput.addEventListener("input", displayBooks);
genreFilter.addEventListener("change", displayBooks);

applyMainTheme();
displayBooks();

